import {test,expect} from 'playwright/test';
import {mkdir,writeFile} from 'node:fs/promises';
import {prepare,ready} from './fixtures/browser.js';

// These coordinates are immutable measurements of the approved collage, not
// screenshots generated by the application. Pixel error is reported honestly;
// functional content, browser text rasterization and live map data also differ.
const panes=[
  {id:'login',x:0,y:0,w:563,h:526,theme:'light'},
  {id:'painel',x:563,y:0,w:717,h:526,theme:'light'},
  {id:'clientes',x:0,y:528,w:469,h:325,theme:'dark'},
  {id:'mapa',x:472,y:528,w:423,h:325,theme:'dark'},
  {id:'dados',x:899,y:528,w:381,h:325,theme:'dark'}
];
for(const pane of panes)test(`approved reference: ${pane.id}`,async({page,context})=>{
  const viewport={width:pane.w*2,height:pane.h*2};await page.setViewportSize(viewport);
  await prepare(page,{authenticated:pane.id!=='login',theme:pane.theme,liveMaps:pane.id==='mapa'});await ready(page);
  if(pane.id!=='login')await page.locator(`.tabs [data-tab="${pane.id}"]`).click();
  if(pane.id==='dados'){await page.locator('#cloudCheck').click();await expect(page.locator('#cloudStatus')).not.toHaveText('Aguardando verificação.');}
  if(pane.id==='mapa'){
    await expect(page.locator('#map canvas')).toBeVisible({timeout:20000});
    await expect.poll(()=>page.evaluate(()=>map?.isStyleLoaded()&&map?.areTilesLoaded()),{timeout:35000}).toBe(true);
  }
  await page.evaluate(()=>document.fonts.ready);
  const geometry=await page.evaluate(()=>{
    const bounds=sel=>{const r=document.querySelector(sel).getBoundingClientRect();return{x:r.x,y:r.y,w:r.width,h:r.height};};
    return{header:bounds('body>header'),sidebar:bounds('.tabs'),login:bounds('.auth-panel'),hero:bounds('.traxio-hero')};
  });
  if(pane.id==='login'){
    expect(Math.abs(geometry.login.x-592)).toBeLessThan(1);
    expect(Math.abs(geometry.login.y-118)).toBeLessThan(1);
    expect(Math.abs(geometry.login.w-498)).toBeLessThan(1);
  }else{
    expect(Math.abs(geometry.header.h-72*viewport.height/650)).toBeLessThan(1);
    expect(Math.abs(geometry.sidebar.w-(pane.id==='painel'?160:164)*viewport.height/650)).toBeLessThan(1);
  }
  await mkdir('docs/captures/reference',{recursive:true});
  const actual=await page.screenshot({path:`docs/captures/reference/${pane.id}-actual.png`,animations:'disabled'});
  const review=await context.newPage();await review.setViewportSize({width:viewport.width*2,height:viewport.height});await review.goto('/assets/approved-mockup.jpg');
  const metrics=await review.evaluate(async({pane,actual})=>{
    const load=src=>new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src=src;});
    const [ref,img]=await Promise.all([load('/assets/approved-mockup.jpg'),load('data:image/png;base64,'+actual)]);
    const approved=document.createElement('canvas');approved.width=img.width;approved.height=img.height;
    const ac=approved.getContext('2d');ac.drawImage(ref,pane.x,pane.y,pane.w,pane.h,0,0,img.width,img.height);
    const current=document.createElement('canvas');current.width=img.width;current.height=img.height;const cc=current.getContext('2d');cc.drawImage(img,0,0);
    const a=ac.getImageData(0,0,img.width,img.height).data,b=cc.getImageData(0,0,img.width,img.height).data;
    let absolute=0,mismatch=0;for(let i=0;i<a.length;i+=4){let d=0;for(let c=0;c<3;c++)d+=Math.abs(a[i+c]-b[i+c]);absolute+=d;if(d/3>24)mismatch++;}
    document.documentElement.innerHTML='<head><title>Approved / actual</title><style>*{box-sizing:border-box}html,body{margin:0;background:#001e2d;overflow:hidden}body{display:flex}canvas,img{display:block}</style></head><body></body>';
    document.body.append(approved,img);
    return{meanAbsoluteRGBError:absolute/(img.width*img.height*3),pixelsDifferingOver24:mismatch/(img.width*img.height),identical:false};
  },{pane,actual:actual.toString('base64')});
  await review.screenshot({path:`docs/captures/reference/${pane.id}-comparison.png`});
  await writeFile(`docs/captures/reference/${pane.id}-metrics.json`,JSON.stringify({reference:pane,viewport,geometry,metrics},null,2));await review.close();
});
